namespace AgentKit.Evaluation;

/// <summary>Identifies one execution of an evaluation plan.</summary>
/// <remarks>A run identity is generated by <see cref="IIdentifierGenerator{TIdentifier}"/> once per <see cref="IEvaluationRunner.RunAsync"/> call. It is distinct from the stable <see cref="EvaluationPlanId"/> and from the agent <see cref="RunId"/> each case produces.</remarks>
public readonly record struct EvaluationRunId
{
    /// <summary>Initializes a non-empty evaluation run identity.</summary>
    /// <param name="value">The globally unique value.</param>
    /// <exception cref="ArgumentOutOfRangeException"><paramref name="value"/> is empty.</exception>
    public EvaluationRunId(Guid value)
    {
        ArgumentOutOfRangeException.ThrowIfEqual(value, Guid.Empty);
        Value = value;
    }

    /// <summary>Gets the globally unique value.</summary>
    public Guid Value { get; }

    /// <summary>Returns the canonical text form.</summary>
    /// <returns>The value in hyphenated form.</returns>
    public override string ToString() => Value.ToString("D");
}
